// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes32 role, address account) public {
        // renounceRole is permissionless regarding initialization state and works for any role/account
        vm.assume(account != address(0));

        // attempt to renounce (contract is not initialized, so no roles are held by anyone;
        // renounceRole does not require any prior role to be held)
        vm.prank(account);
        c.renounceRole(role, account);

        // General rule: after renouncing, the account must NOT hold the role.
        // The reference satisfies this for every input (revoking keeps it false);
        // the mutant grants the role, so hasRole becomes true for some input.
        assertTrue(!c.hasRole(role, account));
    }
}
